def transform(grid):
    if not grid or not grid[0]:
        return grid

    bg_color = grid[0][0]

    # Find the foreground color (the one that's not background)
    fg_color = None
    for row in grid:
        for cell in row:
            if cell != bg_color:
                fg_color = cell
                break
        if fg_color is not None:
            break

    # Determine transformation rule based on foreground color value
    if fg_color == 5:
        # Rule: bg→0, fg→bg
        output = []
        for row in grid:
            new_row = []
            for cell in row:
                if cell == bg_color:
                    new_row.append(0)
                else:
                    new_row.append(bg_color)
            output.append(new_row)
    else:
        # Rule: bg→fg, fg→0
        output = []
        for row in grid:
            new_row = []
            for cell in row:
                if cell == bg_color:
                    new_row.append(fg_color)
                else:
                    new_row.append(0)
            output.append(new_row)

    return output
